import {errorPositions} from './archive.js';
const DAY=86400000,MINUTE=60000;
export const INTERVAL_DAYS=[1,3,7,14,30,60];
export function schedules(attempts){const map=new Map(),seen=new Set();for(const a of [...attempts].filter(a=>typeof a.cardId==='string'&&Number.isFinite(a.at)).sort((a,b)=>a.at-b.at)){const key=a.cardId+':'+(a.sessionId||a.id);if(seen.has(key))continue;seen.add(key);const old=map.get(a.cardId)||{repetitions:0,due:0,reviews:0};let next;if(!a.success)next={repetitions:0,due:a.at+10*MINUTE};else if(a.assisted)next={repetitions:0,due:a.at+DAY};else if(old.due>a.at)next={repetitions:old.repetitions,due:old.due};else{const repetitions=old.repetitions+1;next={repetitions,due:a.at+INTERVAL_DAYS[Math.min(repetitions-1,INTERVAL_DAYS.length-1)]*DAY}}map.set(a.cardId,{...next,reviews:old.reviews+1,last:a.at,lastSuccess:!!a.success})}return map}
export function makeDeck(games,catalog){const errors=errorPositions(games),frequency={};for(const e of errors)frequency[e.theme]=(frequency[e.theme]||0)+1;const personal=errors.map(e=>({id:'personal:'+e.id,theme:e.theme,fen:e.fen,source:'personal',gameId:e.gameId,objective:'Trova una mossa migliore rispetto alla partita.',weight:(frequency[e.theme]||0)+1}));const composed=catalog.map(p=>({...p,source:'catalog',matched:!!frequency[p.theme]||(p.theme==='hanging'&&!!frequency.material),weight:(frequency[p.theme]||0)+(p.theme==='hanging'?(frequency.material||0):0)}));return {cards:[...personal,...composed],errors,frequency}}
export function reviewQueue(cards,attempts,{now=Date.now(),mode='due',source='all',limit=10}={}){const state=schedules(attempts);const eligible=cards.filter(c=>source==='all'||c.source===source).filter(c=>mode==='all'||!state.has(c.id)||state.get(c.id).due<=now).sort((a,b)=>(b.weight-a.weight)||a.id.localeCompare(b.id));const due=eligible.filter(c=>state.has(c.id)&&state.get(c.id).due<=now).sort((a,b)=>state.get(a.id).due-state.get(b.id).due);const fresh=eligible.filter(c=>!state.has(c.id)),personal=fresh.filter(c=>c.source==='personal'),catalog=fresh.filter(c=>c.source!=='personal'),mixed=[];while(personal.length||catalog.length){if(catalog.length)mixed.push(catalog.shift());if(personal.length)mixed.push(personal.shift())}const future=eligible.filter(c=>state.has(c.id)&&state.get(c.id).due>now).sort((a,b)=>state.get(a.id).due-state.get(b.id).due);return [...due,...mixed,...future].slice(0,limit)}
export function reviewSummary(cards,attempts,now=Date.now()){const state=schedules(attempts),values=cards.map(c=>state.get(c.id)).filter(Boolean);return {due:values.filter(s=>s.due<=now).length,new:cards.length-values.length,mastered:values.filter(s=>s.repetitions>=3).length,nextDue:Math.min(...values.filter(s=>s.due>now).map(s=>s.due))||null}}
export function nextReviewText(state,now=Date.now()){if(!state)return '';if(state.due-now<=11*MINUTE)return 'Da ripassare tra circa 10 minuti.';const date=new Date(state.due).toLocaleDateString('it-IT',{day:'numeric',month:'long'});return `Prossimo ripasso: ${date}.`}
